  SetTransitionAllowedInput,
  SetWorkItemLabelsInput,
  SetWorkItemTypeInput,
  ToggleWorkCommentReactionInput,
  UpdateProjectVisibilityInput,
  UpdateWorkItemInput,
  UpdateWorkLabelInput,
  UpdateWorkTypeInput,
