  async listCustomFields(tko_tenantId: string, tko_projectId: string): Promise<WorkCustomFieldDefinition[]> { return this.tko_read(tko_tenantId, async c => (await c.query(`select * from custom_field_definitions where tenant_id=$1 and scope_type='project' and scope_id=$2 order by created_at`, [tko_tenantId,tko_projectId])).rows.map(this.tko_customField)); }
  async setCustomFieldValue(tko_actor: PlatformActor, tko_input: { workItemId: string; fieldId: string; value: unknown; correlationId: string }): Promise<WorkCustomFieldValue> { return this.tko_withTransaction(tko_actor.tenantId, async c => { const tko_item = await c.query(`select project_id from work_items where id=$1 and tenant_id=$2`,[tko_input.workItemId,tko_actor.tenantId]); const tko_field = await c.query(`select * from custom_field_definitions where id=$1 and tenant_id=$2`,[tko_input.fieldId,tko_actor.tenantId]); if (!tko_item.rowCount || !tko_field.rowCount || String(tko_field.rows[0].scope_id) !== String(tko_item.rows[0].project_id)) throw new Error("WORK_CUSTOM_FIELD_NOT_FOUND"); const tko_before = await c.query(`select value_json from custom_field_values where tenant_id=$1 and field_id=$2 and entity_type='work_item' and entity_id=$3`,[tko_actor.tenantId,tko_input.fieldId,tko_input.workItemId]); await c.query(`insert into custom_field_values (tenant_id,field_id,entity_type,entity_id,value_json) values ($1,$2,'work_item',$3,$4::jsonb) on conflict (field_id,entity_type,entity_id) do update set value_json=excluded.value_json`,[tko_actor.tenantId,tko_input.fieldId,tko_input.workItemId,JSON.stringify(tko_input.value)]); const tko_value: WorkCustomFieldValue = {id:`${tko_input.fieldId}:${tko_input.workItemId}`,tenantId:tko_actor.tenantId,type:"custom_field_value",fieldId:tko_input.fieldId,workItemId:tko_input.workItemId,value:tko_input.value}; await this.tko_history(c,tko_actor,tko_input.workItemId,`custom:${tko_input.fieldId}`,tko_before.rowCount ? tko_before.rows[0].value_json : null,tko_input.value); await this.tko_emit(c,tko_actor,"work.custom_field_value_set.v1","work.item",{workItemId:tko_input.workItemId,fieldId:tko_input.fieldId},"work.custom_field.value_set","work_item",tko_input.workItemId,tko_input.correlationId); return tko_value; }); }
