  async addDependency(tko_actor: PlatformActor,tko_input:{sourceWorkItemId:string;targetWorkItemId:string;relationType:WorkItemRelationType;correlationId:string}):Promise<void>{await this.tko_withTransaction(tko_actor.tenantId,async c=>{const tko_r=await c.query(`select id,project_id from work_items where tenant_id=$1 and id=any($2::uuid[]) for update`,[tko_actor.tenantId,[tko_input.sourceWorkItemId,tko_input.targetWorkItemId]]);if(tko_r.rowCount!==2||tko_input.sourceWorkItemId===tko_input.targetWorkItemId)throw new Error("WORK_RELATION_INVALID");if(tko_input.relationType==="blocks"||tko_input.relationType==="blocked_by"){const [from,to]=tko_input.relationType==="blocks"?[tko_input.sourceWorkItemId,tko_input.targetWorkItemId]:[tko_input.targetWorkItemId,tko_input.sourceWorkItemId];const tko_cycle=await c.query(`with recursive graph(from_id,to_id) as (select case when relation_type='blocked_by' then target_work_item_id else source_work_item_id end,case when relation_type='blocked_by' then source_work_item_id else target_work_item_id end from work_item_relations where tenant_id=$1 and relation_type in ('blocks','blocked_by')),reachable(id) as (select to_id from graph where from_id=$2 union select graph.to_id from graph join reachable on graph.from_id=reachable.id) select 1 from reachable where id=$3 limit 1`,[tko_actor.tenantId,to,from]);if(tko_cycle.rowCount)throw new Error("WORK_RELATION_CYCLE");}const tko_id=crypto.randomUUID();const tko_inserted=await c.query(`insert into work_item_relations (id,tenant_id,source_work_item_id,target_work_item_id,relation_type,created_by_member_id) values ($1,$2,$3,$4,$5,$6) on conflict (tenant_id,source_work_item_id,target_work_item_id,relation_type) do nothing returning *`,[tko_id,tko_actor.tenantId,tko_input.sourceWorkItemId,tko_input.targetWorkItemId,tko_input.relationType,tko_actor.memberId]);if(!tko_inserted.rowCount)return;await this.tko_emit(c,tko_actor,"work.work_item_relation_created.v1","work.item",{sourceWorkItemId:tko_input.sourceWorkItemId,targetWorkItemId:tko_input.targetWorkItemId,relationType:tko_input.relationType,relationId:tko_id},"work.work_item.relation_created","work_item_relation",tko_id,tko_input.correlationId);});}
