  private tko_projectInvitation=(r:Row):ProjectInvitation=>({id:String(r.id),tenantId:String(r.tenant_id),type:"project_invitation",projectId:String(r.project_id),inviteeEmail:r.invitee_email?String(r.invitee_email):null,projectRole:r.project_role as ProjectInvitation["projectRole"],createdByMemberId:String(r.created_by_member_id),expiresAt:new Date(String(r.expires_at)),redeemedAt:tko_date(r.redeemed_at),redeemedByMemberId:r.redeemed_by_member_id?String(r.redeemed_by_member_id):null,revokedAt:tko_date(r.revoked_at),createdAt:new Date(String(r.created_at))});
  private tko_projectQuery=(tko_where:string)=>`select p.*, coalesce(array_agg(pm.member_id) filter (where pm.member_id is not null), array[]::uuid[]) as explicit_member_ids, coalesce(jsonb_object_agg(pm.member_id::text, pm.project_role) filter (where pm.member_id is not null), '{}'::jsonb) as project_member_roles from projects p left join project_members pm on pm.project_id=p.id and pm.tenant_id=p.tenant_id where ${tko_where} group by p.id`;
