  private tko_status=(r:Row):WorkflowStatus=>({id:String(r.id),tenantId:String(r.tenant_id),type:"workflow_status",workflowId:String(r.workflow_id),name:String(r.name),category:r.category as WorkflowStatus["category"],colorToken:String(r.color_token),description:String(r.description??""),sortOrder:Number(r.sort_order)});
