  private async tko_item(c:PoolClient,r:Row):Promise<WorkItem>{const [a,p,l,w]=await Promise.all([c.query(`select member_id from work_item_assignees where tenant_id=$1 and work_item_id=$2`,[r.tenant_id,r.id]),c.query(`select key from projects where tenant_id=$1 and id=$2`,[r.tenant_id,r.project_id]),c.query(`select label_id from work_item_labels where tenant_id=$1 and work_item_id=$2`,[r.tenant_id,r.id]),c.query(`select member_id from work_item_watchers where tenant_id=$1 and work_item_id=$2`,[r.tenant_id,r.id])]);const tko_projectKey=String(p.rows[0]?.key??"");return {id:String(r.id),tenantId:String(r.tenant_id),type:"work_item",projectId:String(r.project_id),sequenceNo:Number(r.sequence_no),key:`${tko_projectKey}-${Number(r.sequence_no)}`,workTypeId:String(r.work_type_id),parentId:r.parent_id?String(r.parent_id):null,workflowId:String(r.workflow_id),statusId:String(r.status_id),title:String(r.title),description:String(r.description_text),priority:r.priority as WorkItem["priority"],reporterMemberId:String(r.reporter_member_id),assigneeMemberIds:a.rows.map(x=>String(x.member_id)),watcherMemberIds:w.rows.map(x=>String(x.member_id)).sort(),labelIds:l.rows.map(x=>String(x.label_id)).sort(),startAt:tko_date(r.start_at),dueAt:tko_date(r.due_at),estimateMinutes:r.estimate_minutes===null?null:Number(r.estimate_minutes),rank:String(r.rank),sprintId:r.sprint_id?String(r.sprint_id):null,version:Number(r.version),completedAt:tko_date(r.completed_at),archivedAt:tko_date(r.archived_at),createdAt:new Date(String(r.created_at)),updatedAt:new Date(String(r.updated_at))};}
  private async tko_commentsFor(c:PoolClient,tenantId:string,workItemId:string):Promise<WorkComment[]>{const tko_result=await c.query(`select * from work_comments where tenant_id=$1 and work_item_id=$2 and deleted_at is null order by created_at`,[tenantId,workItemId]);return Promise.all(tko_result.rows.map(async row=>{const tko_comment=this.tko_comment(row);const [reactions,attachments]=await Promise.all([c.query(`select * from work_comment_reactions where tenant_id=$1 and comment_id=$2 order by created_at`,[tenantId,tko_comment.id]),c.query(`select * from work_comment_attachments where tenant_id=$1 and comment_id=$2 order by created_at`,[tenantId,tko_comment.id])]);return {...tko_comment,reactions:reactions.rows.map(this.tko_commentReaction),attachments:attachments.rows.map(this.tko_commentAttachment)};}));}
