  private async tko_transitionsFor(c:PoolClient,tenantId:string,workflowId:string):Promise<WorkflowTransition[]>{const tko_r=await c.query(`select t.from_status_id,t.to_status_id,coalesce((t.restrictions_json->>'allowed')::boolean,true) as allowed from workflow_transitions t where t.tenant_id=$1 and t.workflow_id=$2 and (t.from_status_id is null or exists (select 1 from workflow_statuses s where s.id=t.from_status_id and s.tenant_id=$1 and s.workflow_id=$3)) and exists (select 1 from workflow_statuses s2 where s2.id=t.to_status_id and s2.tenant_id=$1 and s2.workflow_id=$3) order by t.from_status_id nulls first,t.to_status_id`,[tenantId,workflowId,workflowId]);return tko_r.rows.map(row=>({fromStatusId:row.from_status_id===null?null:String(row.from_status_id),toStatusId:String(row.to_status_id),allowed:Boolean(row.allowed)}));}
  /** Workflows with no persisted transition rows allow every status change (backward compat). */
  private async tko_requireTransition(c:PoolClient,tenantId:string,workflowId:string,fromStatusId:string,toStatusId:string):Promise<void>{if(fromStatusId===toStatusId)return;const tko_anyRows=await c.query(`select 1 from workflow_transitions where tenant_id=$1 and workflow_id=$2 limit 1`,[tenantId,workflowId]);if(!tko_anyRows.rowCount)return;const tko_row=await c.query(`select coalesce((restrictions_json->>'allowed')::boolean,true) as allowed from workflow_transitions where tenant_id=$1 and workflow_id=$2 and from_status_id=$3::uuid and to_status_id=$4::uuid`,[tenantId,workflowId,fromStatusId,toStatusId]);if(!tko_row.rowCount||!tko_row.rows[0].allowed)throw new Error("WORK_ITEM_TRANSITION_NOT_ALLOWED");}
